  // Only configuration heartbeats continue in the background; output deadlines stay on the FC.
  function startClock(){stopClock();if(typeof Worker!=='function')return;try{clockUrl=URL.createObjectURL(new Blob(["setInterval(()=>postMessage('tick'),1000)"],{type:'text/javascript'}));clockWorker=new Worker(clockUrl);clockWorker.onmessage=()=>{if(active)poll()};clockWorker.onerror=e=>{e.preventDefault();stopClock()};}catch{stopClock()}}
  function stopClock(){clockWorker?.terminate();clockWorker=null;if(clockUrl)URL.revokeObjectURL(clockUrl);clockUrl='';}
  async function pauseOutputs(){if(!active||starting||!same()||!a.owned())return;const output=outputRun,bench=Number(status?.benchMode||0);if(!output&&!bench)return;const e=epoch;try{if(output)await endOutput(output);else await cmd('motor_stop');if(e!==epoch||!active)return;status=await cmd('setup_ping');if(bench===4||escPhase==='high'||escPhase==='low'){escPhase='idle';escStarted=escLowDone=false;complete[4]=false;for(const n of ['escPowerOff','tones','skipEsc'])escChecks[n]=false;stepErrors[4]='ESC output stopped when leaving the page. Repeat calibration with the battery disconnected.';if(jobWait){jobWait.reject(Error(stepErrors[4]));jobWait=null;}if(step===4)render();}note('Motor / ESC outputs stopped. Setup progress and control are retained.');publishProgress();buttons();}catch(error){if(e===epoch)await stop('Could not confirm outputs stopped: '+error.message)}}
  root.querySelector('[data-fs=next]').onclick=()=>{if(active&&!busy&&!stopTask&&!outputRun&&!outputCleanup&&!status?.benchMode&&(complete[step]||skipped[step])){step=toolName?(step===0?steps.indexOf(toolName):10):step+1;render()}};root.querySelector('[data-fs=skip]').onclick=()=>{if(!active||busy||stopTask||outputRun||outputCleanup||status?.benchMode||step===0||step===10||step===7&&source==='PPM'&&!receiverWizard?.requiredDetected)return;skipped[step]=!complete[step];publishProgress();step=toolName?10:step+1;render();note('Pending checks remain listed in red on Telemetry.');};root.querySelector('[data-fs=back]').onclick=()=>{if(!busy&&!stopTask&&!outputRun&&!outputCleanup&&!status?.benchMode&&step>0){sweep=false;step=toolName?0:step-1;render()}};root.querySelector('[data-fs=stop]').onclick=()=>stop();root.querySelector('[data-fs=restart]').onclick=async()=>{if(busy||active||stopTask)return;await stop();step=0;status=null;complete.fill(false);skipped.fill(false);stepErrors.fill('');render();note('Reconnect the correct kit, remove all propellers, then Detect board / start setup.');};
  document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseOutputs();else if(active)poll()});addEventListener('pagehide',()=>stop());root.closest('dialog')?.addEventListener('close',()=>stop());root.closest('dialog')?.addEventListener('cancel',()=>stop());setInterval(poll,300);render();
  return {stop,pauseOutputs,update:()=>{if(active&&(!same()||!a.owned()))stop('Setup ownership changed.');buttons()},openTool:name=>{if(active)throw Error('Stop the current setup before changing tools.');toolName=steps.includes(name)?name:null;step=0;status=null;render()},get active(){return active}};
